INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Blackbox-Test?', 2, '[{"text": "Test ohne interne Strukturkenntnis", "correct": true, "because": "Fokus auf Eingabe/Ausgabe"}, {"text": "Test mit vollem Code-Zugriff", "correct": false, "because": "Whitebox-Test"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Blackbox-Test?', 3, '[{"text": "Funktionalität überprüfen", "correct": true, "because": "Anforderungen testen"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Code optimieren", "correct": false, "because": "Nicht der Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zum Blackbox-Test?', 5, '[{"text": "Äquivalenzklassenbildung", "correct": true, "because": "Eingabepartitionierung"}, {"text": "Grenzwertanalyse", "correct": true, "because": "Randbereiche testen"}, {"text": "Code-Inspektion", "correct": false, "because": "Whitebox-Test"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Blackbox-Tests prüfen Eingaben und Ausgaben. b) Sie erfordern Code-Kenntnisse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Code-Kenntnis nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Blackbox-Test?', 4, '[{"text": "Interne Struktur", "correct": true, "because": "Nicht relevant"}, {"text": "Anforderungen", "correct": false, "because": "Grundlage"}, {"text": "Testfälle", "correct": false, "because": "Wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Blackbox-Test die Funktionalität überprüft?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Verhalten"}, {"text": "Nein", "correct": false, "because": "Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist typisch für einen Blackbox-Test?', 3, '[{"text": "Äquivalenzklassenbildung", "correct": true, "because": "Eingaben gruppieren"}, {"text": "Code-Abdeckung", "correct": false, "because": "Whitebox-Test"}, {"text": "Debugging", "correct": false, "because": "Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Durchführung eines Blackbox-Tests?', 5, '[{"text": "Testfälle erstellen", "correct": true, "because": "Basierend auf Anforderungen"}, {"text": "Eingaben definieren", "correct": true, "because": "Prüft Ausgaben"}, {"text": "Code analysieren", "correct": false, "because": "Nicht Blackbox"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Blackbox-Tests prüfen Anforderungen. b) Sie sind nur für große Projekte geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Blackbox-Test unwichtig?', 4, '[{"text": "Interne Logik", "correct": true, "because": "Nicht betrachtet"}, {"text": "Testabdeckung", "correct": false, "because": "Funktionalität prüfen"}, {"text": "Anforderungsspezifikation", "correct": false, "because": "Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Blackbox-Test die interne Struktur kennen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Eingabe/Ausgabe"}, {"text": "Ja", "correct": false, "because": "Blackbox-Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Blackbox-Test für Fachinformatiker?', 4, '[{"text": "Fokus auf Nutzerperspektive", "correct": true, "because": "Realistische Tests"}, {"text": "Einfache Testfallerstellung", "correct": true, "because": "Anforderungsbasierte"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Blackbox-Tests nur Fehler finden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Funktionalität"}, {"text": "Ja", "correct": false, "because": "Breiter Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Blackbox-Test?', 3, '[{"text": "Anforderungen", "correct": true, "because": "Testbasis"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Code-Struktur", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Blackbox-Tests können Grenzwerte prüfen. b) Sie ersetzen Whitebox-Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Blackbox-Test?', 5, '[{"text": "Fehlende Code-Abdeckung", "correct": true, "because": "Interne Struktur unbekannt"}, {"text": "Eingeschränkte Fehlersuche", "correct": true, "because": "Nur Ausgaben geprüft"}, {"text": "Schnellere Tests", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim Blackbox-Test?', 3, '[{"text": "Testfälle entwerfen", "correct": true, "because": "Anforderungsprüfung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Blackbox-Test automatisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. mit Tools"}, {"text": "Nein", "correct": false, "because": "Automatisierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Blackbox-Tests nutzen?', 4, '[{"text": "Selenium", "correct": true, "because": "Automatisierte Tests"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
